1519	Status SegmentImpl::create_vector_index(
1520	    const std::string &column, const IndexParams::Ptr &index_params,
1521	    int concurrency, SegmentMeta::Ptr *segment_meta,
1522	    std::unordered_map<std::string, VectorColumnIndexer::Ptr> *vector_indexers,
1523	    std::unordered_map<std::string, VectorColumnIndexer::Ptr>
1524	        *quant_vector_indexers) {
1525	  auto field = collection_schema_->get_vector_field(column);
1526	  SegmentMeta::Ptr new_segment_meta;
1527	  if (*segment_meta == nullptr) {
1528	    new_segment_meta = std::make_shared<SegmentMeta>(*segment_meta_);
1529	    new_segment_meta->remove_writing_forward_block();
1530	  } else {
1531	    new_segment_meta = *segment_meta;
1532	  }
1533	
1534	  if (segment_meta_->vector_indexed(column) &&
1535	      *field->index_params() == *index_params) {
1536	    // if segment is already indexed and index params are same, skip create
1537	    *segment_meta = new_segment_meta;
1538	    return Status::OK();
1539	  }
1540	  new_segment_meta->add_indexed_vector_field(column);
1541	
1542	  auto vector_index_params =
1543	      std::dynamic_pointer_cast<VectorIndexParams>(index_params);
1544	
1545	  if (vector_index_params->quantize_type() == QuantizeType::UNDEFINED) {
1546	    auto block_id = allocate_block_id();
1547	
1548	    auto field_with_new_index_params = std::make_shared<FieldSchema>(*field);
1549	    field_with_new_index_params->set_index_params(index_params);
1550	
1551	    std::string index_file_path = FileHelper::MakeVectorIndexPath(
1552	        path_, column, segment_meta_->id(), block_id);
1553	    if (FileHelper::FileExists(index_file_path)) {
1554	      LOG_WARN(
1555	          "Index file[%s] already exists (possible crash residue); cleaning "
1556	          "and overwriting.",
1557	          index_file_path.c_str());
1558	      FileHelper::RemoveFile(index_file_path);
1559	    }
1560	    auto vector_indexer = merge_vector_indexer(
1561	        index_file_path, column, *field_with_new_index_params, concurrency);
1562	    if (!vector_indexer.has_value()) {
1563	      return vector_indexer.error();
1564	    }
1565	
1566	    vector_indexers->insert({column, vector_indexer.value()});
1567	
1568	    new_segment_meta->remove_vector_persisted_block(column);
1569	    BlockMeta block;
1570	    block.set_id(block_id);
1571	    block.set_type(BlockType::VECTOR_INDEX);
1572	    block.set_columns({column});
1573	    block.set_min_doc_id(doc_ids_.front());
1574	    block.set_max_doc_id(doc_ids_.back());
1575	    block.set_doc_count(doc_ids_.size());
1576	    new_segment_meta->add_persisted_block(block);
1577	
1578	    *segment_meta = new_segment_meta;
1579	
1580	  } else {
1581	    auto original_index_params =
1582	        std::dynamic_pointer_cast<VectorIndexParams>(field->index_params());
1583	    const auto configured_flat_data_type =
1584	        segment_detail::FlatStorageDataTypeForField(
1585	            field->data_type(), vector_index_params->flat_data_type());
1586	    const auto desired_flat_data_type =
1587	        configured_flat_data_type == DataType::UNDEFINED
1588	            ? field->data_type()
1589	            : configured_flat_data_type;
1590	
1591	    core::IndexProvider::Pointer raw_vector_provider;
1592	
1593	    const auto current_flat_params =
1594	        vector_indexers_[column].size() == 1
1595	            ? std::dynamic_pointer_cast<FlatIndexParams>(
1596	                  vector_indexers_[column][0]->field_schema().index_params())
1597	            : nullptr;
1598	    const auto current_flat_data_type =
1599	        current_flat_params &&
1600	                current_flat_params->storage_data_type() != DataType::UNDEFINED
1601	            ? current_flat_params->storage_data_type()
1602	            : field->data_type();
1603	
1604	    if (!(vector_index_params->metric_type() ==
1605	              original_index_params->metric_type() &&
1606	          vector_indexers_[column].size() == 1 &&
1607	          current_flat_data_type == desired_flat_data_type)) {
1608	      BlockID block_id = allocate_block_id();
1609	
1610	      auto field_with_flat = std::make_shared<FieldSchema>(*field);
1611	      field_with_flat->set_index_params(MakeDefaultVectorIndexParams(
1612	          vector_index_params->metric_type(),
1613	          vector_index_params->use_flat_contiguous_memory(),
1614	          configured_flat_data_type));
1615	
1616	      std::string index_file_path = FileHelper::MakeVectorIndexPath(
1617	          path_, column, segment_meta_->id(), block_id);
1618	      if (FileHelper::FileExists(index_file_path)) {
1619	        LOG_WARN(
1620	            "Index file[%s] already exists (possible crash residue); cleaning "
1621	            "and overwriting.",
1622	            index_file_path.c_str());
1623	        FileHelper::RemoveFile(index_file_path);
1624	      }
1625	      auto vector_indexer = merge_vector_indexer(index_file_path, column,
1626	                                                 *field_with_flat, concurrency);
1627	      if (!vector_indexer.has_value()) {
1628	        return vector_indexer.error();
1629	      }
1630	
1631	      vector_indexers->insert({column, vector_indexer.value()});
1632	
1633	      new_segment_meta->remove_vector_persisted_block(column, false);
1634	      BlockMeta block;
1635	      block.set_id(block_id);
1636	      block.set_type(BlockType::VECTOR_INDEX);
1637	      block.set_columns({column});
1638	      block.set_min_doc_id(meta()->min_doc_id());
1639	      block.set_max_doc_id(meta()->max_doc_id());
1640	      block.set_doc_count(meta()->doc_count());
1641	      new_segment_meta->add_persisted_block(block);
1642	      if (vector_index_params->type() == IndexType::HNSW_RABITQ) {
1643	        raw_vector_provider = vector_indexer.value()->create_index_provider();
1644	      }
1645	    } else if (vector_index_params->type() == IndexType::HNSW_RABITQ) {
1646	      raw_vector_provider =
1647	          vector_indexers_[column][0]->create_index_provider();
1648	    }
1649	
1650	    auto field_with_new_index_params = std::make_shared<FieldSchema>(*field);
1651	    field_with_new_index_params->set_index_params(index_params);
1652	
1653	    // For HNSW_RABITQ, PrepareQuantizeField trains a reformer with
1654	    // raw_vector_provider. IVF_RABITQ trains inside its builder. For other
1655	    // quantize types, field_with_new_index_params is reused as-is.
1656	    std::shared_ptr<FieldSchema> field_for_quantize;
1657	    {
1658	      auto s = SegmentHelper::PrepareQuantizeField(*field_with_new_index_params,
1659	                                                   raw_vector_provider,
1660	                                                   &field_for_quantize);
1661	      CHECK_RETURN_STATUS(s);
1662	    }
1663	
1664	    auto quant_block_id = allocate_block_id();
1665	    std::string index_file_path = FileHelper::MakeQuantizeVectorIndexPath(
1666	        path_, column, segment_meta_->id(), quant_block_id);
1667	    if (FileHelper::FileExists(index_file_path)) {
1668	      LOG_WARN(
1669	          "Index file[%s] already exists (possible crash residue); cleaning "
1670	          "and overwriting.",
1671	          index_file_path.c_str());
1672	      FileHelper::RemoveFile(index_file_path);
1673	    }
1674	    auto vector_indexer = merge_vector_indexer(
1675	        index_file_path, column, *field_for_quantize, concurrency);
1676	    if (!vector_indexer.has_value()) {
1677	      return vector_indexer.error();
1678	    }
1679	
1680	    quant_vector_indexers->insert({column, vector_indexer.value()});
1681	
1682	    new_segment_meta->remove_vector_persisted_block(column, true);
1683	    BlockMeta block;
1684	    block.set_id(quant_block_id);
1685	    block.set_type(BlockType::VECTOR_INDEX_QUANTIZE);
1686	    block.set_columns({column});
1687	    block.set_min_doc_id(meta()->min_doc_id());
1688	    block.set_max_doc_id(meta()->max_doc_id());
1689	    block.set_doc_count(meta()->doc_count());
1690	    new_segment_meta->add_persisted_block(block);
1691	
1692	    *segment_meta = new_segment_meta;
1693	  }
1694	
1695	  return Status::OK();
1696	}
